// Puzzle data for Feud, the daily crowd-survey game. SERVER-ONLY: imported by
// app/feud/page.js (which strips everything but the questions before the
// client sees it) and by app/api/feud/route.js (which buckets and scores
// against the house pool + real answers).
//
// Five prompts a day. Each prompt carries:
//   q       — the survey question shown to players.
//   answers — the canonical answer buckets: `c` is the display label, `k` the
//             alias keys (quiz keyHit matching: substring either way, or every
//             word of a multi-word key present). The label itself is also
//             matched, so `k` only needs variants. Free-text answers that
//             match no bucket form dynamic buckets by normalized string.
//   house   — ~40 pre-written house votes (indices into `answers`), shaped to
//             a plausible crowd. They seed the pool until more than ten real
//             players are in (lib/feud-score.js HOUSE_CUTOFF), then retire.
//
// When banking more days: fresh, universally-answerable prompts (no trivia,
// no regional bias), never reuse a prompt, house always sums to 40 with no
// zero-vote bucket, and run the alias self-collision audit before shipping
// (every label + alias must resolve to its own bucket through the matcher).
//
// ─────────────────────────────────────────────────────────────────────────────
// `house` IS AN AUTHORED ESTIMATE OF A CROWD. IT IS NOT MEASURED PLAY.
// ─────────────────────────────────────────────────────────────────────────────
// Every house array in this file — all 610 of them — was written by the author
// of the board, not observed from players. Nothing in the pipeline turns it
// into observed play. The author ranks the buckets in the order they believe a
// broad audience would answer, then a fixed 40-vote ladder is laid over that
// ranking (scripts/gen-feud.mjs). So a house array is a guess with a shape,
// dressed as 40 ballots, and the percentage a player sees while the house is
// still in the pool is a percentage OF THAT GUESS.
//
// That is a legitimate thing to ship, because `house` exists only to give the
// first players of the day a plausible field to be scored against, and
// lib/feud-score.js retires it pool-wide the moment an eleventh real player
// locks in (HOUSE_CUTOFF = 10). What would NOT be legitimate is presenting it
// as measurement anywhere a player can see it. If a board is ever seeded from
// real `feud_picks` rows, say so on that board and stop letting this note cover
// it.
//
// ─────────────────────────────────────────────────────────────────────────────
// THE MATCHER IS RULES, NOT AI — WHICH IS WHY ALIASES ARE THE WHOLE CRAFT.
// ─────────────────────────────────────────────────────────────────────────────
// lib/feud-match.js decides which bucket a typed answer belongs to with a fixed
// rule ladder (normalize, stem, one synonym table, then score every bucket and
// keep the best). Nothing in it knows what an answer MEANS. Write the alias
// list by asking what a real player would actually type. The rules give you
// plurals, -ing/-ed, filler words, compound spacing ("chap stick"), one-key
// typos on words of five letters or more, and the shared synonym table
// (tv/television, soda/pop/coke, sofa/couch, fridge/refrigerator, kid/child,
// mom/mum, ...). They give you nothing else: "duvet" does not reach
// "comforter" and "the bill" does not reach "the check" unless you write it.
//
// The other half is that an alias must not reach a SIBLING bucket. The rule
// that avoids essentially all of it: NO TWO BUCKETS ON ONE PROMPT SHARE A
// CONTENT WORD. Two buckets ending in the same noun are one bucket to the
// matcher ("Chocolate cake" / "Coffee cake"), and so are two where one's words
// sit inside the other's ("Coffee" / "Coffee maker", "Fries" / "Sweet potato
// fries"). Beware the synonym table doing it for you: "nap" IS "sleep",
// "holiday" IS "vacation", "sweet" IS "candy", "mate" IS "friend", "lift" IS
// "elevator", "shop" IS "store". scripts/verify-feud.mjs is the gate.
//
// Note a real stemmer asymmetry, since it costs points silently: "smoothies"
// stems to "smoothy" while "smoothie" stays "smoothie", "cheeses" collapses to
// "chee", "hoagies" to "hoagy". A bucket whose noun ends -ie, -y or -se is
// reachable in ONE number only unless the other is written down as an alias.
// scripts/gen-feud.mjs adds those mechanically for boards it builds.
//
// ─────────────────────────────────────────────────────────────────────────────
// AUTHORING RULES (checked by scripts/verify-feud.mjs from FEUD_RULES_FROM)
// ─────────────────────────────────────────────────────────────────────────────
//   * FIVE prompts every day, one board per day, `num` contiguous and in date
//     order, `quizId` / `dateLabel` derived from `live` and never typed.
//   * SIX TO NINE answer buckets a prompt — a band, not a floor. No more than
//     55% of a segment on one count, and every count in the band present. The
//     2026-08/09 bank is 81% eights; do not copy that shape.
//   * EVERY BUCKET carries at least one alias.
//   * HOUSE sums to exactly 40, indices in range, NO zero-vote bucket (a
//     zero-vote bucket is unreachable in lib/feud-score.js, so it is a trap
//     rather than an answer), and runs monotone non-increasing — the bucket
//     order IS the popularity claim.
//   * NO PROMPT TEXT repeats another anywhere in the bank.
//   * ANSWER LABELS have a ceiling across a segment: four uses, and only two
//     for a label the earlier bank already runs ten times or more (pizza,
//     coffee, ice cream, snacks). Frozen counts cannot be lowered; the job of
//     a new segment is to stop making them worse.
//   * CROWD SHAPE is calibrated against the bank that already shipped: tops run
//     8-19 of 40 with the mass between 8 and 13. A steeper house makes the
//     obvious answer pay more and the board easier, so a runaway favorite is
//     rationed rather than the house style.
//   * PROMPT CATEGORY variety (at most 22 of 310 in one category, five distinct
//     categories on every board, no category in the same slot two days running)
//     is enforced in scripts/gen-feud.mjs, which is the only place the category
//     tags exist — they are authoring metadata and are not stored here.
//
// FEUD HAS NO SUNDAY EDITION. `sunday` is false on every board, including the
// eighteen that fall on a real Sunday; feud is absent from
// lib/sunday-editions.js and no ramp is described anywhere. The field is
// vestigial (CLAUDE.md, "Adding a BRAND NEW daily game", names this exact
// anti-pattern). Do not start setting it true to look thorough: that badges a
// Sunday Edition that does not exist and breaks the registry's two-way sync
// rule. Giving feud a real Sunday needs a rule here, an entry in
// lib/sunday-editions.js and a check in verify-feud.mjs, in one pass.
//
// Boards 61-122 (2026-09-30 to 2026-11-30) were built by scripts/gen-feud.mjs
// from the authored corpus in scripts/feud-prompts.mjs.
